# Wrappers for the Rust functions registered in src/rust/src/lib.rs.
# Normally generated by rextendr::document(); keep in sync by hand.

#' @usage NULL
#' @useDynLib replconnect, .registration = TRUE
NULL

protocol_version <- function() .Call(wrap__protocol_version)

rs_start <- function(cwd, project, r_version) {
  .Call(wrap__rs_start, cwd, project, r_version)
}

rs_info <- function() .Call(wrap__rs_info)

rs_address <- function(x) .Call(wrap__rs_address, x)

rs_diagnostics <- function() .Call(wrap__rs_diagnostics)

rs_stop <- function() .Call(wrap__rs_stop)

rs_bump_version <- function() .Call(wrap__rs_bump_version)

rs_version <- function() .Call(wrap__rs_version)

rs_evaluating <- function() .Call(wrap__rs_evaluating)

rs_notify <- function(method, params, subscribed_only) {
  .Call(wrap__rs_notify, method, params, subscribed_only)
}

rs_subscribe <- function(connection) .Call(wrap__rs_subscribe, connection)

rs_unsubscribe_all <- function() .Call(wrap__rs_unsubscribe_all)

rs_log <- function(message) .Call(wrap__rs_log, message)

rs_to_json <- function(x) .Call(wrap__rs_to_json, x)

rs_from_json <- function(text) .Call(wrap__rs_from_json, text)
